using UnityEngine;using UnityEngine.UI;
// Repositions authored objects only when viewport/stock visibility changes; never draws or constructs UI.
public sealed class ForgeLegacyLayout:MonoBehaviour {
 public RectTransform[] states,actions;public RectTransform materialArea,materialContent,debug,progress,developerButton,clock,guide,tutorialPanel,tutorialEditor;public RectTransform developer,sales,output;public GridLayoutGroup resourceGrid;public GridLayoutGroup materialGrid;int width,height,count=-1;
 static void Place(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
 // Re-enabling the screen must preserve user window placement.
 void LateUpdate(){if(developer&&resourceGrid)resourceGrid.cellSize=new Vector2(Mathf.Max(120,(developer.rect.width-40)/2),87);int visible=0;foreach(Transform child in materialContent)if(child.gameObject.activeSelf)visible++;if(width==Screen.width&&height==Screen.height&&count==visible)return;bool firstLayout=width==0,viewportChanged=width!=Screen.width||height!=Screen.height;width=Screen.width;height=Screen.height;count=visible;float top=width>=960?4:124;for(int i=0;i<states.Length;i++)Place(states[i],12+i*120,top,112,112);for(int i=0;i<actions.Length;i++)Place(actions[i],width-122-120*i,4,112,112);Place(debug,width-122,124,112,28);Place(developerButton,width-122,156,112,28);Place(progress,12,height-36,190,28);Place(clock,216,height-36,200,28);// Keep the transparent material viewport clear of the utility buttons on wide screens.
 float materialWidth=width-(width>=960?146:24);float columnStep=materialGrid.cellSize.x+materialGrid.spacing.x,rowStep=materialGrid.cellSize.y+materialGrid.spacing.y;int columns=Mathf.Max(1,Mathf.FloorToInt((materialWidth+materialGrid.spacing.x)/columnStep));materialGrid.constraintCount=columns;int rows=Mathf.CeilToInt(visible/(float)columns);Place(materialArea,12,top+124,materialWidth,Mathf.Min(rows*rowStep,Mathf.Max(rowStep,height-(top+124)-180)));materialContent.sizeDelta=new Vector2(0,rows*rowStep);
 if(viewportChanged)foreach(var window in new[]{sales,output,firstLayout?null:guide})if(window){window.sizeDelta=new Vector2(Mathf.Min(window.rect.width,width-24),Mathf.Min(window.rect.height,height-24));window.anchoredPosition=new Vector2(Mathf.Clamp(window.anchoredPosition.x,12,Mathf.Max(12,width-window.rect.width-12)),-Mathf.Clamp(-window.anchoredPosition.y,12,Mathf.Max(12,height-window.rect.height-12)));}
 if(developer){developer.sizeDelta=new Vector2(Mathf.Min(816,width-24),Mathf.Min(488,height-24));developer.anchoredPosition=new Vector2(Mathf.Max(12,width-developer.rect.width-12),-Mathf.Max(12,height-developer.rect.height-12));}
 if(guide&&firstLayout){float bookTop=Mathf.Min(top+124+rows*rowStep-5,height-240);guide.sizeDelta=new Vector2(Mathf.Min(420,width-140),Mathf.Min(660,height-bookTop-12));guide.anchoredPosition=new Vector2(Mathf.Max(118,width-guide.rect.width-12),-bookTop);}
 if(tutorialPanel){float panel=Mathf.Min(460,(width-36)*.48f);Place(tutorialPanel,12,12,panel,height-24);Place(tutorialEditor,panel+24,190,Mathf.Min(600,Mathf.Max(260,width-panel-36)),Mathf.Min(400,height-202));}
 }
}
